+// SPDX-License-Identifier: Apache-2.0
+// SPDX-FileCopyrightText: Copyright contributors to the vLLM project
+
+//! HTTP-level coverage for the Rust OpenAI Responses API.
+
+use std::sync::Arc;
+
+use axum::body::{Body, to_bytes};
+use axum::http::{Request, StatusCode};
+use serde_json::json;
+use serial_test::serial;
+use tower::Service as _;
+use vllm_engine_core_client::protocol::output::EngineCoreFinishReason;
+
+use super::*;
+
+fn reasoning_answer_output_specs() -> Vec<(Vec<u32>, Option<EngineCoreFinishReason>)> {
+    vec![
+        (token_ids("<think>Need tool.</think>"), None),
+        (bytes_to_token_ids(b"answer"), None),
+        // '!' is the fake tokenizer's stop token; it is suppressed from the
+        // visible text but carries the finish reason.
+        (vec![b'!' as u32], Some(EngineCoreFinishReason::Stop)),
+    ]
+}
+
+fn weather_function_tool() -> serde_json::Value {
+    json!({
+        "type": "function",
+        "name": "get_weather",
+        "description": "Get weather",
+        "parameters": {
+            "type": "object",
+            "properties": {"city": {"type": "string"}}
+        }
+    })
+}
+
+async fn responses_call(app: &axum::Router, body: serde_json::Value) -> axum::response::Response {
+    app.clone()
+        .call(
+            Request::builder()
+                .method("POST")
+                .uri("/v1/responses")
+                .header("content-type", "application/json")
+                .body(Body::from(body.to_string()))
+                .expect("build request"),
+        )
+        .await
+        .expect("call app")
+}
+
+/// Run one request as a stream and return the response object carried by its
+/// terminal event.
+async fn responses_stream_terminal(
+    app: &axum::Router,
+    mut body: serde_json::Value,
+) -> serde_json::Value {
+    body["stream"] = json!(true);
+    let response = responses_call(app, body).await;
+    assert_eq!(response.status(), StatusCode::OK);
+    let body = to_bytes(response.into_body(), usize::MAX).await.expect("read body");
+    let mut payloads = sse_json_payloads(std::str::from_utf8(&body).expect("utf8 body"));
+    payloads.pop().expect("terminal event")["response"].take()
+}
+
+#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
+#[serial]
+async fn responses_empty_model_uses_served_model() {
+    let (app, engine_task) = test_app_with_engine_handle().await;
+    let response = responses_stream_terminal(&app, json!({"model": "", "input": "hello"})).await;
+    engine_task.await.expect("mock engine task");
+    assert_eq!(response["model"], "Qwen/Qwen1.5-0.5B-Chat");
+}
+
+#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
+#[serial]
+async fn responses_sampling_metadata_matches_engine_defaults_and_overrides() {
+    for (overrides, temperature, top_p, min_p) in [
+        (json!({}), 0.6, 0.95, 0.0),
+        (
+            json!({
+                "temperature": 0.2, "top_p": 0.8, "min_p": 0.1, "max_output_tokens": 7,
+                "presence_penalty": 0.5, "frequency_penalty": -0.5
+            }),
+            0.2,
+            0.8,
+            0.1,
+        ),
+    ] {
+        // The engine resolves `max_tokens` against the context, so echo what
+        // it received rather than a constant.
+        let engine_values = Arc::new(std::sync::Mutex::new(None));
+        let backend = FakeChatBackend {
+            sampling_hints: vllm_text::SamplingHints {
+                default_temperature: Some(0.6),
+                default_top_p: Some(0.95),
+                ..Default::default()
+            },
+            ..FakeChatBackend::new()
+        };
+        let (app, engine_task) =
+            test_app_with_backend_and_engine_request_check(Arc::new(backend), {
+                let engine_values = Arc::clone(&engine_values);
+                move |request| {
+                    let params = request.sampling_params.as_ref().unwrap();
+                    assert_eq!(params.temperature, temperature);
+                    assert_eq!(params.top_p, top_p);
+                    assert_eq!(params.min_p, min_p);
+                    *engine_values.lock().unwrap() = Some((
+                        params.max_tokens,
+                        params.presence_penalty,
+                        params.frequency_penalty,
+                    ));
+                }
+            })
+            .await;
+        let mut request = json!({"input": "hello"});
+        request.as_object_mut().unwrap().extend(overrides.as_object().unwrap().clone());
+        let response = responses_stream_terminal(&app, request).await;
+        engine_task.await.expect("mock engine task");
+        let (max_tokens, presence_penalty, frequency_penalty) =
+            engine_values.lock().unwrap().expect("engine request");
+        if let Some(requested) = overrides.get("max_output_tokens") {
+            assert_eq!(json!(max_tokens), *requested);
+        }
+        assert!((response["temperature"].as_f64().unwrap() - f64::from(temperature)).abs() < 1e-6);
+        assert!((response["top_p"].as_f64().unwrap() - f64::from(top_p)).abs() < 1e-6);
+        assert_eq!(response["max_output_tokens"], json!(max_tokens));
+        assert_eq!(response["presence_penalty"], json!(presence_penalty));
+        assert_eq!(response["frequency_penalty"], json!(frequency_penalty));
+    }
+}
